namespace CSharpPracticum.Tasks.Level2;
internal enum NotificationType{Email,Sms,Push}internal interface INotification{void Send(string message);}internal class EmailNotification:INotification{public void Send(string m)=>Console.WriteLine($"Email: {m}");}internal class SmsNotification:INotification{public void Send(string m)=>Console.WriteLine($"SMS: {m}");}internal class PushNotification:INotification{public void Send(string m)=>Console.WriteLine($"Push: {m}");}internal static class NotificationFactory{public static INotification Create(NotificationType t)=>t switch{NotificationType.Email=>new EmailNotification(),NotificationType.Sms=>new SmsNotification(),NotificationType.Push=>new PushNotification(),_=>throw new ArgumentOutOfRangeException(nameof(t))};}
internal class Task29_Notifications:ITask{public string Title=>"Задание 29: Паттерн Фабрика (уведомления)";public string Description=>"Создавать уведомления через фабрику по enum.";public string[] Requirements=>new[]{"INotification.Send.","Email, Sms, Push реализации.","NotificationFactory.Create(NotificationType).", "Продемонстрировать отправку."};public void Run(){foreach(NotificationType t in Enum.GetValues<NotificationType>())NotificationFactory.Create(t).Send("Сообщение");}}
